from pool import configure_pool

def check_isolation():
    base_template = {"dsn": "pg://prod", "pool": {"min": 5, "timeout_seconds": 2}}
    overrides_tenant1 = {"pool": {"max": 20, "timeout_seconds": 99}}
    overrides_tenant2 = {"pool": {"max": 20}}

    opts_tenant1 = configure_pool(base_template, overrides_tenant1)
    opts_tenant2 = configure_pool(base_template, overrides_tenant2)

    assert opts_tenant1.timeout_seconds == 99
    assert opts_tenant2.timeout_seconds == 2

check_isolation()
